import{_ as o,o as r,c as n,ag as e}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"敌意建筑：当\\"变简单\\"变成不让人久留","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/design/hostile-architecture.md","filePath":"topics/design/hostile-architecture.md"}'),s={name:"topics/design/hostile-architecture.md"};function a(i,t,g,u,l,d){return r(),n("div",null,[...t[0]||(t[0]=[e('<h1 id="敌意建筑-当-变简单-变成不让人久留" tabindex="-1">敌意建筑：当&quot;变简单&quot;变成不让人久留 <a class="header-anchor" href="#敌意建筑-当-变简单-变成不让人久留" aria-label="Permalink to &quot;敌意建筑：当&quot;变简单&quot;变成不让人久留&quot;">​</a></h1><blockquote><p>来源：en.wikipedia ⟪Hostile architecture⟫、⟪Camden bench⟫、⟪Mosquito (device)⟫、⟪Simme seat⟫、⟪Defensive design⟫（消歧义指向）；当年报道：BBC（2014-06-09 / 2014-06-13 / 2019-03-09）、Guardian（2014-06-07 / 2014-06-12 / 2015-02-18）、CNN（2017-12-07 正反辩论）、Willamette Week（2019-06-19）；一手厂商资料：Factory Furniture 官网（Wayback 存档） 链接：<a href="https://en.wikipedia.org/wiki/Hostile_architecture" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Hostile_architecture</a> ｜ <a href="https://www.bbc.com/news/uk-england-london-27832298" target="_blank" rel="noreferrer">https://www.bbc.com/news/uk-england-london-27832298</a> ｜ <a href="https://edition.cnn.com/style/article/new-dean-harvey-james-furzer-hostile-architecture-debate/index.html" target="_blank" rel="noreferrer">https://edition.cnn.com/style/article/new-dean-harvey-james-furzer-hostile-architecture-debate/index.html</a> 核实状态：✅ = 已核对来源；⚠️ = 未取得一手确认，本文档不当事实使用（核实日期 2026-09-20）</p></blockquote><h2 id="一、术语-一堆近义词-和一个容易被忽略的区分" tabindex="-1">一、术语：一堆近义词，和一个容易被忽略的区分 <a class="header-anchor" href="#一、术语-一堆近义词-和一个容易被忽略的区分" aria-label="Permalink to &quot;一、术语：一堆近义词，和一个容易被忽略的区分&quot;">​</a></h2><p>维基条目名是 <strong>Hostile architecture</strong>（敌意建筑）✅，定义是：<strong>用建成环境中的要素有目的地引导行为、把某些公众排除出公共空间</strong>；&quot;敌意&quot;的要害在于它通常是<strong>隐蔽地</strong>（偶尔公开地）让人主动离开，而不是把人赶走。</p><p>维基开篇列的同义/近义词 ✅：defensive architecture、hostile design、unpleasant design、exclusionary design、anti-homeless architecture、defensive urban design。这么多别名本身就说明一件事：<strong>这个概念是在公众争论里长出来的，不是在学术里定名的</strong>。</p><p>几个必须说清的边界：</p><ul><li><strong>提出者与首用年份：⚠️ 未核实。</strong> 维基只说&quot;这个词是晚近的&quot;，没给出提出者。可以确认的硬信息是：英文维基 <strong>Hostile architecture 词条最早版本是 2015-02-23</strong>（编辑者 Wittylama）✅——这只说明它进入主流话语的下限，<strong>不等于词源</strong>。</li><li><strong>&quot;defensive design&quot; 在维基是另一个词条</strong> ✅：指的是&quot;为防止误用而做的容错设计&quot;（典型例子是英式 BS 1363 插头，防触电的设计）。词条顶部有 About 模板指向 Hostile architecture——<strong>别把&quot;防御性设计&quot;和&quot;敌意建筑&quot;混为一谈</strong>，前者保护使用者，后者排除使用者。</li><li><strong>unpleasant design</strong> 的用法来源可定位到 Savic &amp; Savic 编的同名书《Unpleasant Design》（G.L.O.R.I.A.，Belgrade，ISBN 978-86-910911-1-8），其官网给出的定义是&quot;公共空间中的障碍物、心理与感官操纵&quot; ✅，站点 unpleasant.pravi.me 现已 404、只剩 Wayback 存档（2011-10-14 起有快照）✅；<strong>但该书的出版年份与&quot;提出年份&quot;本轮未从一手页确认 ⚠️</strong>。</li><li><strong>&quot;Design Apartheid&quot;</strong>（设计隔离）出自 <strong>Rob Imrie</strong>，指建成环境里&quot;同质化与健全主义（ableist）假设&quot; ✅。</li></ul><h2 id="二、形式与技术清单-每条都尽量挂真实案例" tabindex="-1">二、形式与技术清单（每条都尽量挂真实案例） <a class="header-anchor" href="#二、形式与技术清单-每条都尽量挂真实案例" aria-label="Permalink to &quot;二、形式与技术清单（每条都尽量挂真实案例）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形式</th><th>说明</th><th>案例（含年份）</th></tr></thead><tbody><tr><td>尖刺 / 凸起</td><td>最直白的一种，也最容易引发抗议</td><td>2014 伦敦 Southwark 私宅门口防露宿尖刺 ✅</td></tr><tr><td>分段长椅</td><td>加扶手或隔断，使平躺不可能</td><td>瑞典吕勒奥站&quot;防流浪者&quot;长椅：<strong>每张七根铁条、间距 47cm</strong> ✅</td></tr><tr><td>倾斜 / 弧面座面</td><td>坐着会滑，等于&quot;只能斜靠&quot;</td><td>2010 马尔默 City Tunnel 新站台长椅倾斜到几乎无法坐，被投诉到<strong>平等监察专员</strong> ✅</td></tr><tr><td>独立小座椅（Simme seat）</td><td>附在站牌杆上，用于人行道极窄处；<strong>在流浪者扎营普遍的地方作为排斥性设计使用，目的就是阻止躺卧</strong> ✅</td><td>en.wikipedia ⟪Simme seat⟫</td></tr><tr><td>防露营巨石</td><td>把可扎营的空地变成不可用的地形</td><td>美国俄勒冈交通厅自 <strong>2013 年</strong>起在波特兰投放至少 <strong>6–8 处</strong>，花费超 <strong>100 万美元</strong>；ODOT 发言人 Don Hamilton 原话：&quot;巨石是我们阻止非法露营者进入禁入区最有效的方法&quot; ✅（Willamette Week 2019-06-19）</td></tr><tr><td>围栏 / 格栅</td><td>拦住可躺卧的空间</td><td>斯德哥尔摩 2015 年花 <strong>20 万瑞典克朗</strong>（约 22,900 美元） ✅</td></tr><tr><td>超声波驱赶（Mosquito）</td><td>高频音，主要针对青少年</td><td><strong>Howard Stapleton 发明，2005 年取得专利</strong>，首测于威尔士 Barry，同年由其公司 Compound Security Solutions 上市；2008 年末版本为双频 17.4kHz/8kHz、最大 108dB；<strong>2006 年获搞笑诺贝尔和平奖</strong>；德国联邦职业安全与健康研究所报告称无法认证其完全安全 ✅</td></tr><tr><td>感官驱赶</td><td>刺眼照明、洒水、播放古典音乐、噪音</td><td><strong>旧金山某市民礼堂夜间播放电锯、摩托、风钻声</strong> ✅；洛杉矶 Skid Row 夜间洒水、2013 年纽约 Strand 书店喷水、2016 年利物浦旧英格兰银行大楼夜间覆盖涂油倾斜钢板 ✅</td></tr><tr><td>移除（最隐蔽的一种）</td><td>不是加东西，而是把东西拿走</td><td>见下文第四节</td></tr></tbody></table><p><strong>一个容易被忽略的事实</strong>：这些手段里，最有效、也最难被拍下来抗议的，是<strong>没有形状的那种</strong>——把长椅拆了。</p><h2 id="三、深度个案" tabindex="-1">三、深度个案 <a class="header-anchor" href="#三、深度个案" aria-label="Permalink to &quot;三、深度个案&quot;">​</a></h2><h3 id="_1-2014-年伦敦-southwark-防露宿尖刺-一场十天之内从安装到拆除的公关灾难" tabindex="-1">1）2014 年伦敦 Southwark 防露宿尖刺：一场十天之内从安装到拆除的公关灾难 <a class="header-anchor" href="#_1-2014-年伦敦-southwark-防露宿尖刺-一场十天之内从安装到拆除的公关灾难" aria-label="Permalink to &quot;1）2014 年伦敦 Southwark 防露宿尖刺：一场十天之内从安装到拆除的公关灾难&quot;">​</a></h3><ul><li>位置：<strong>Southwark Bridge Road 一处私宅门口的凹龛</strong>；<strong>2014-06-07 Guardian 首发报道</strong>（Andrew Horton 拍照，经 Twitter 扩散）✅</li><li><strong>2014-06-09 BBC</strong>：请愿已超 <strong>4,000</strong> 人；时任伦敦市长 Boris Johnson 称这些尖刺 &quot;ugly, self defeating and stupid&quot;；Crisis 的 Katharine Sacks-Jones 给出背景数据——伦敦露宿三年涨 <strong>75%</strong>、全英 <strong>36%</strong>，前一年伦敦有 <strong>6,400 人</strong>露宿 ✅</li><li><strong>2014-06-13 BBC</strong>：尖刺<strong>已被移除</strong>，请愿签名涨到<strong>超 12 万</strong>；Southwark 议员 Peter John 表态；<strong>Tesco 同步宣布拆除 Regent Street 门店外的 studs</strong> ✅</li><li>同期的 BBC 综述《The cornucopia of anti-homeless sleeping design》（2014-06-09，Justin Parkinson）✅ 记录了英国巴士站长椅的三种退化形态：<strong>要么明显倾斜（人一睡就滚下去），要么被扶手打断，有些干脆变成 &quot;perch boards&quot;——连坐都坐不了</strong>；同文还提到火奴鲁鲁把巴士站长椅换成圆形混凝土凳。</li><li><strong>这条个案最值得记的不是尖刺，而是替代品的滑坡</strong>：&quot;让人不能躺&quot;和&quot;让人不能坐&quot;之间只差一点点，而这一点点在制度上没有任何阻力。<strong>椅子的可用性可以无限退化，直到它只是个形状。</strong></li></ul><h3 id="_2-camden-bench-一张被称作-敌意建筑巅峰-的长椅-和它两套不一致的说明书" tabindex="-1">2）Camden bench：一张被称作&quot;敌意建筑巅峰&quot;的长椅，和它两套不一致的说明书 <a class="header-anchor" href="#_2-camden-bench-一张被称作-敌意建筑巅峰-的长椅-和它两套不一致的说明书" aria-label="Permalink to &quot;2）Camden bench：一张被称作&quot;敌意建筑巅峰&quot;的长椅，和它两套不一致的说明书&quot;">​</a></h3><ul><li>2012 年由 Camden 自治市委托、安装于 Holborn 一带，厂商 <strong>Factory Furniture</strong>，被称作 &quot;the pinnacle of hostile architecture&quot; ✅</li><li><strong>两套清单，内容不一致——这个矛盾本身是本文档最有价值的证据</strong> ✅： <ul><li><strong>维基版（转述 Kurt Kohlstedt）</strong>：反睡眠、反毒品交易、反乱扔、反盗窃、反滑板、反涂鸦，另可作路障；</li><li><strong>厂商官网原文（Wayback 存档）</strong>：阻rough sleeping（脊状顶面与斜面）、阻drug dealing（无缝可藏）、防盗包（前后凹槽）、减少乱扔、易搬迁（自带吊点）、可选 HMV 版并达 <strong>BSi PAS 68</strong> 评级（车辆防撞）。</li><li>差异点在<strong>涂鸦与滑板</strong>：厂家没把它们写进设计目标，是维基转述加上去的。<strong>引用时不能把两者混成一句。</strong></li></ul></li><li>尺寸：2700×550×650mm；投放点 Great Queen St 与 High Holborn ✅</li><li>同一厂家还有两款被 CNN 点名的产品（2017-12-07 报道图片说明）✅：<strong>FLO granite</strong>（波浪顶面，难躺卧、光面无缝可藏毒）与 <strong>Scroll Seat</strong>（扶手使平躺不可能）。</li></ul><h3 id="_3-无障碍-话术-厂商自己说漏了嘴" tabindex="-1">3）&quot;无障碍&quot;话术：厂商自己说漏了嘴 <a class="header-anchor" href="#_3-无障碍-话术-厂商自己说漏了嘴" aria-label="Permalink to &quot;3）&quot;无障碍&quot;话术：厂商自己说漏了嘴&quot;">​</a></h3><p>这是整份材料里最硬的一段证据，两处独立的证词指向同一个机制：</p><ul><li><strong>CNN 2017-12-07</strong> 的正反辩论（Factory Furniture 联合创始人 Dean Harvey vs 建筑师 James Furzer）中，Harvey 原话 ✅：<strong>&quot;我们被要求给长椅加 studs，最后我建议改成扶手，因为扶手有一举两得之用&quot;</strong>；他还说&quot;事后加装本身就是概念阶段的糟糕设计&quot;。</li><li>瑞典案例 ✅：国铁 Jernhusen 在吕勒奥站用了&quot;防流浪者&quot;长椅（七根铁条、间距 47cm），其新闻官起初称&quot;主要是为了老人与残障者起坐方便&quot;，受访时<strong>承认车站秩序问题影响了设计</strong>。</li></ul><p><strong>结论</strong>：导致&quot;扶手&quot;被广泛采用的那个理由——&quot;方便老人起身&quot;——在至少两个独立案例里被其提出方自己承认为<strong>事后包装</strong>。<strong>&quot;无障碍&quot;是排斥设计最好用的语言掩护</strong>：它听起来像关怀，实际功能是<strong>制造不连续面</strong>。</p><h3 id="_4-最主流的形态其实是-减法" tabindex="-1">4）最主流的形态其实是&quot;减法&quot; <a class="header-anchor" href="#_4-最主流的形态其实是-减法" aria-label="Permalink to &quot;4）最主流的形态其实是&quot;减法&quot;&quot;">​</a></h3><p>Fredrik Edin 的论点 ✅：<strong>&quot;移除&quot;才是最普遍的形式</strong>——2021 年纽约地铁在社交媒体称&quot;拆除长椅以防流浪者睡觉&quot;（后称是失误）；斯德哥尔摩中央站 2015 年拆长椅改椅子；吕勒奥站同理。</p><p>Nils Norman 的三段退化链 ✅（Guardian 2015-02-18）：<strong>&quot;benches become bum-free, which in turn become &#39;perches&#39;, which are in turn removed&quot;</strong>——长椅先变成&quot;无处可躺的凳&quot;，再变成&quot;只能靠不能坐的托&quot;，最后被直接拿掉。</p><p><strong>链条的终点是消失。</strong> 而公众为什么拆不掉它？因为<strong>没有被拆除的长椅不会被拍下来</strong>——反对敌意建筑的照片只需要一张尖刺，反对&quot;长椅不见了&quot;却需要一张过去的照片。</p><h3 id="_5-东亚-能核实多少写多少" tabindex="-1">5）东亚：能核实多少写多少 <a class="header-anchor" href="#_5-东亚-能核实多少写多少" aria-label="Permalink to &quot;5）东亚：能核实多少写多少&quot;">​</a></h3><p>新宿站地下通道存在防露宿设计的实物，Wikimedia Commons 文件元数据记录为 <strong>2007-10-31 拍摄</strong>，归入 Hostile street furniture / Nishi-Shinjuku 分类 ✅。但<strong>本轮没有取得该处设计者、委托方或设计意图的媒体报道 ⚠️</strong>——所以本文档只写&quot;存在此类物件及其拍摄时间&quot;，不推断其动机，也不给年份之外的细节。</p><h2 id="四、代价-谁在被排除" tabindex="-1">四、代价：谁在被排除 <a class="header-anchor" href="#四、代价-谁在被排除" aria-label="Permalink to &quot;四、代价：谁在被排除&quot;">​</a></h2><ul><li>受影响的主要群体 ✅（Selena Savic 语，Guardian 2014-06-12）：<strong>无家可归者、青少年、穷人、缺乏组织的边缘群体</strong>。</li><li>一份容易被忽略的清单：想坐一会儿的<strong>老人</strong>、走累了需要靠着休息的<strong>残障人士</strong>、滑板与聚会占据公共空间被视作问题的<strong>年轻人</strong>。<strong>&quot;不方便久留&quot;从来不是只针对流浪者</strong>——只是流浪者是最没能力反抗的那一群人。</li><li><strong>维基自己承认的知识空白</strong> ✅：<strong>截至 2020 年 3 月，尚无大规模实证研究测量敌意建筑对流浪者福祉的影响。</strong> 这和品牌趋同那篇的情形一样：<strong>定性证据充分、定量证据缺失</strong>——不许替它补数据。</li></ul><h2 id="五、反对与纠偏-什么真的推动了改变" tabindex="-1">五、反对与纠偏：什么真的推动了改变 <a class="header-anchor" href="#五、反对与纠偏-什么真的推动了改变" aria-label="Permalink to &quot;五、反对与纠偏：什么真的推动了改变&quot;">​</a></h2><ul><li><strong>受害者视角组织化</strong>：Crisis、People Over Profit（后者称此类椅子是 &quot;attempt to hide the homeless&quot;）✅</li><li><strong>建筑师批评</strong>：Jonathan Adams 称这类椅子 &quot;ubiquitous and horrible&quot; ✅；James Furzer 在 CNN 辩论中的核心论点不是&quot;难看&quot;，而是<strong>露营与朋友聚会并不构成犯罪</strong> ✅——注意这场辩论双方（Harvey 与 Furzer）<strong>共享同一个定义</strong>（&quot;敌意建筑=用建筑要素控制人类行为&quot;），分歧在于<strong>哪些行为算反社会</strong>。</li><li><strong>媒体报道能直接拆掉东西</strong>：2014 伦敦尖刺十天内被移除、Tesco 同期自行拆除 ✅——<strong>这是&quot;曝光有效&quot;的最明确案例</strong>。</li><li><strong>制度层面在动</strong>：2019-03-09 BBC 报道威尔士有人呼吁禁止&quot;反无家可归者长椅&quot;，但请愿仅 120 人、Swansea 与 Cardiff 两议会均否认存在故意设计 ✅——<strong>说明这件事在地方政治层面还没形成有效约束</strong>。</li><li><strong>公共座椅长期减少的量化数据：⚠️ 未取得。</strong> Guardian 的开放平台接口返回 401，本轮未能拿到可靠统计。现有可引证据全是<strong>定性</strong>的（Edin 的&quot;移除最常见&quot;、Norman 的三段退化链、纽约地铁 2021 年的声明）。<strong>不要编造统计。</strong></li></ul><h2 id="六、与极简主义的关系-为什么椅子越做越简单" tabindex="-1">六、与极简主义的关系：为什么椅子越做越简单 <a class="header-anchor" href="#六、与极简主义的关系-为什么椅子越做越简单" aria-label="Permalink to &quot;六、与极简主义的关系：为什么椅子越做越简单&quot;">​</a></h2><p>这是本文档存在的理由。公共长椅&quot;变简单&quot;有两个完全不同的驱动力，而<strong>它们在外观上常常长得一样</strong>：</p><p><strong>驱动力 A：省成本。</strong> 少工序、少材料、少部件。结果是<strong>平的、光的、少的</strong>——表面平整（好加工）、结构简单（好安装）、没有多余装饰（省钱）。</p><p><strong>驱动力 B：有意的排斥。</strong> 结果是<strong>斜的、凸的、分段的、带吊点的、带特殊涂层的</strong>。注意：<strong>这些&quot;简单&quot;其实是加法，是加成本、加设计、加功能</strong>——Camden bench 自带吊点、可选 PAS 68 车辆防撞评级、特殊防涂涂层 ✅，一个纯粹省钱的项目不会做这些。</p><p><strong>所以形状的复杂方向是相反的</strong>：省钱的简化让表面<strong>变平</strong>；排斥性的&quot;简化&quot;让表面变成<strong>能滚落人的斜面</strong>。</p><p><strong>现场判据（四问，直接可用）</strong>：</p><ol><li><strong>只要看有没有分割件</strong>：扶手在<strong>两端</strong>（中间可躺，属于防跌落或无障碍）还是在<strong>每 47cm 一根</strong>（不可躺，属于排斥）？✅ 吕勒奥站是后者。</li><li><strong>斜面朝哪边</strong>：座面微微前倾是人体工学（防止久坐塌腰），<strong>陡到人会滑下去</strong>是排斥（马尔默站台案例）✅。</li><li><strong>有没有&quot;为排斥而付的钱&quot;</strong>：自带吊点（便于夜间整体移走）、PAS 68 防撞、防涂涂层、无缝可藏物——这些是<strong>成本证据</strong>，说明简化不是省钱驱动的。</li><li><strong>先看有没有，再看简不简单</strong>：长椅被<strong>移除</strong>是排斥的最纯粹形态（Edin、Norman 的退化链）✅。<strong>在&quot;变简单&quot;之前，先问它是否还在。</strong></li></ol><h2 id="七、一句话" tabindex="-1">七、一句话 <a class="header-anchor" href="#七、一句话" aria-label="Permalink to &quot;七、一句话&quot;">​</a></h2><p><strong>极简在公共空间里有一个隐藏的第四种动机——不是美、不是成本、不是最小冒犯，而是排除：把椅子做简单，最简单的方式是让它不再是一张椅子。</strong> 主文档问&quot;省略装饰还是省略能力&quot;，在街上要问得更狠一点：<strong>省略的是装饰，还是那个人？</strong></p><hr><blockquote><p>关键词：极简主义、敌意建筑、排斥性设计、公共空间、长椅、无家可归、城市治理、无障碍话术、成本削减、现场判据、Camden bench、且慢核实 关联：</p><ul><li><code>topics/design/minimalism-death-of-detail.md</code>：本文第六节是主文档判据（less, but better vs less, but cheaper）在公共空间的最尖锐版本，主文档第三节的&quot;最小冒犯&quot;在这里露出反面——冒犯被转移给了最没能力反抗的人</li><li><code>topics/design/less-but-better-engineering.md</code>：现场四问与工程判据同构（省掉的是装饰还是能力）；&quot;减法是加法&quot;这一条也是工程里&quot;看起来精简实则加成本&quot;的同一现象</li><li><code>topics/design/logo-convergence.md</code>：最小冒犯在品牌上产生中性，在城市里产生排除——同一机制的两种后果</li><li><code>topics/psychology/</code>：隐蔽性是关键设计原则（若它看起来像恶意，公众会抗议；看起来像&quot;无障碍&quot;，就没人反对）</li><li><code>topics/career-observation/</code>：城市治理与&quot;可见性问题&quot;的转移——把问题从视野里移走，而不是解决</li></ul></blockquote><blockquote><p>整理日期：2026-09-20</p></blockquote>',41)])])}const c=o(s,[["render",a]]);export{q as __pageData,c as default};
